import java.util.*;

public class Main {
    static final int T = 99;
    static final int C = 15;
    static final long INF = 0x3f3f3f3fL;
    static final int N = 50 * T + 2;
    static final int M = 2 * N * C + N + 7;

    static class Flow {
        int[] par = new int[N];
        int[] first = new int[N];
        int[] nxt = new int[2 * M];
        int[] ep = new int[2 * M];
        long[] flo = new long[2 * M];
        long[] cap = new long[2 * M];
        long[] cost = new long[2 * M];
        int m;

        void init() {
            m = 0;
            Arrays.fill(first, -1);
            Arrays.fill(flo, 0);
        }

        void add_edge(int a, int b, long c, long p) {
            nxt[m] = first[ep[m] = a];
            first[ep[m]] = m;
            cap[m] = c;
            cost[m] = p;
            m++;
            nxt[m] = first[ep[m] = b];
            first[ep[m]] = m;
            cap[m] = 0;
            cost[m] = -p;
            m++;
        }
        void add_edge(int a, int b, long c) {
            add_edge(a, b, c, 0);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.printf(Locale.US, "%.10f%n", 0.0); // To mimic fixed precision output

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        final int source = 0;
        final int sink = n * T + 1;
        Flow flow = new Flow();
        flow.init();

        for (int i = 0; i < k; i++) {
            int a = sc.nextInt();
            flow.add_edge(source, a, 1);
        }
        for (int t = 0; t < T; t++) {
            flow.add_edge(1 + t * n, sink, INF);
            if (t > 0) {
                for (int i = 1; i <= n; i++) {
                    flow.add_edge(i + (t - 1) * n, i + t * n, INF);
                }
            }
        }

        for (int i = 0; i < m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            for (int j = 0; j < C; j++) {
                long cost = (long) (j + 1) * (j + 1) - (long) j * j;
                for (int t = 1; t < T; t++) {
                    flow.add_edge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                    flow.add_edge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
                }
            }
        }

        long[] result = minCostMaxFlow(flow, source, sink, N);
        long price = result[0];
        long flowValue = result[1];
        if (flowValue != k) {
            throw new RuntimeException("Flow not sufficient");
        }
        System.out.println(price);
        sc.close();
    }

    static long[] minCostMaxFlow(Flow flow, int s, int t, int n) {
        long[] dist = new long[n];
        long[] potential = new long[n];
        int[] inq = new int[n];
        int[] q = new int[n];
        boolean[] vis = new boolean[n];

        Arrays.fill(potential, 0);
        // Bellman-Ford for initial potentials
        for (int i = 0; i < n; i++) {
            for (int e = 0; e < flow.m; e++) {
                if (flow.cap[e] > 0) {
                    int v = flow.ep[e ^ 1];
                    int u = flow.ep[e];
                    if (potential[v] > potential[u] + flow.cost[e]) {
                        potential[v] = potential[u] + flow.cost[e];
                    }
                }
            }
        }

        long flowVal = 0;
        long costVal = 0;

        while (true) {
            Arrays.fill(dist, INF);
            Arrays.fill(inq, -1);
            dist[s] = 0;
            int qs = 0;
            q[qs++] = s;
            inq[s] = 0;

            // Dijkstra with potentials
            while (qs > 0) {
                int u = q[0];
                for (int i = 0, j = 1; i < qs - 1; i++, j++) {
                    int minIdx = i;
                    for (int k = i + 1; k < qs; k++) {
                        if (dist[q[k]] < dist[q[minIdx]]) {
                            minIdx = k;
                        }
                    }
                    // Swap q[i] and q[minIdx]
                    int temp = q[i]; q[i] = q[minIdx]; q[minIdx] = temp;
                }
                int u = q[0];
                inq[u] = -1;
                int sizeQ = qs;
                for (int i = 0; i < sizeQ; i++) {
                    int v = q[i];
                }
                // Remove u from queue
                System.arraycopy(q, 1, q, 0, qs - 1);
                qs--;
                for (int e = flow.first[u]; e != -1; e = flow.nxt[e]) {
                    int v = flow.ep[e ^ 1];
                    if (flow.cap[e] > 0) {
                        long newDist = dist[u] + potential[u] - potential[v] + flow.cost[e];
                        if (dist[v] > newDist) {
                            dist[v] = newDist;
                            flow.par[v] = e;
                            if (inq[v] == -1) {
                                q[qs++] = v;
                                inq[v] = 1;
                            }
                        }
                    }
                }
            }
            if (dist[t] == INF) break;

            for (int i = 0; i < n; i++) {
                if (dist[i] < INF) {
                    potential[i] += dist[i];
                }
            }

            long df = Long.MAX_VALUE;
            for (int e = flow.par[t], v = t; v != s; e = flow.par[v], v = flow.ep[e]) {
                df = Math.min(df, flow.cap[e]);
            }
            flowVal += df;
            costVal += df * potential[t];

            for (int e = flow.par[t], v = t; v != s; e = flow.par[v], v = flow.ep[e]) {
                flow.cap[e] -= df;
                flow.cap[e ^ 1] += df;
                // flip flow
            }

        }
        return new long[]{costVal, flowVal};
    }
